const Q=require('./aquatic'), A=require('node:assert/strict'),fs=require('fs');let results={},checks=[];function ck(n,v){A.ok(v,n);checks.push(n)}
function run(s,w,n){s.weather=w;let error=0;for(let i=0;i<n;i++){Q.tick(s);for(let x of Object.values(s.last)){A.ok(Number.isFinite(x)&&Math.abs(x)<1e-6);error=Math.max(error,Math.abs(x))}for(let r of s.aqua)for(let k of Q.names)for(let e of ['c','n','p'])A.ok(Number.isFinite(r[k][e])&&r[k][e]>=-1e-10)}return {...Q.metrics(s),error,spawn:s.aquaEvents.spawnC,hatch:s.aquaEvents.hatchC,mature:s.aquaEvents.matureC}}
for(let seed of [42,17,73]){let s=Q.create(seed);let drought=run(s,'drought',360),rain=run(s,'rain',120),recovery=run(s,'rain',240);results[seed]={drought,rain,recovery};ck('balanços e estoques válidos '+seed,Math.max(drought.error,rain.error,recovery.error)<1e-6);ck('retorno da água '+seed,rain.wet>drought.wet)}
let z=Q.create();for(let r of z.aqua){for(let k of ['fish','juvenile','eggs'])r[k]={c:0,n:0,p:0};r.cohorts=[]}let end=run(z,'rain',120);ck('sem reaparecimento de peixes extintos',end.fish===0&&end.juvenile===0&&end.eggs===0);
fs.writeFileSync('recovery42-results.json',JSON.stringify({checks,results},null,2));for(let [seed,r] of Object.entries(results)) console.log(seed,[r.drought,r.rain,r.recovery].map(x=>({fish:x.fish,young:x.juvenile,eggs:x.eggs,larvae:x.larvae,shrimp:x.shrimp})));console.log(checks)
